#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto do_op = [&](int x, int y){
        assert(x>0 && y>0 && x+y<n);
        ops.push_back({x,y});
        vector<int> np;
        int m = n-x-y;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<x+m;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p = np;
    };

    for(int k=0;k<n-1;k++){
        int pos=-1;
        for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
        if(pos==k) continue;

        // Move element from pos to position k
        // Step 1: move element to position n-1 if not already there
        if(pos != n-1){
            // op(pos+1, n-1-pos): takes last (n-1-pos) elements = [pos+1..n-1]
            // middle = [pos+1 .. pos] = empty since x+y = pos+1+n-1-pos = n... no, need x+y<n
            // Try: op with x=pos-k, y=n-1-pos if k>0
            // After: [p[pos+1]..p[n-1], p[pos-k]..p[pos], p[k]..p[pos-k-1]]
            // Element at pos goes to position (n-1-pos) + (pos - (pos-k)) = n-1-pos+k... not obvious

            // Simple: bring to last position first
            // op(1, n-1-pos): element at pos, now pos is in middle, goes to pos - 1 + (n-1-pos) = n-2... 
            // Just rotate: op(pos, n-1-pos) if pos>0 and n-1-pos>0 and pos+n-1-pos=n-1<n
            if(pos>0 && n-1-pos>0){
                do_op(pos, n-1-pos); // element at pos goes to n-1-pos (first of middle? no)
                // After: [pos..n-2, (empty middle if pos+n-1-pos=n-1), 0..pos-1] -> p[n-1] then middle then first
                // Actually element at pos: it's in "first x" part last element -> goes to end
            }
            for(int i=0;i<n;i++) if(p[i]==k+1){pos=i;break;}
        }
        if(pos==k) continue;
        // Now element is somewhere, try op(n-1-k, pos-(n-1-k)) or direct
        if(pos>k && pos<n-1 && (n-1-pos)>0 && (pos-k)>0 && (n-1-pos)+(pos-k)<n){
            do_op(pos-k, n-1-pos);
        } else if(pos==n-1 && k<n-1){
            int y=1; int x=n-1-k; 
            if(x>0 && y>0 && x+y<n) do_op(x,y);
        }
        // verify
        for(int i=0;i<n;i++) if(p[i]==k+1){pos=i;break;}
        if(pos!=k){
            // fallback: try all possible single ops
            for(int x=1;x<n;x++) for(int y=1;x+y<n;y++){
                vector<int> tp(n);
                int idx=0;
                for(int i=n-y;i<n;i++) tp[idx++]=p[i];
                for(int i=x;i<n-y;i++) tp[idx++]=p[i];
                for(int i=0;i<x;i++) tp[idx++]=p[i];
                int pp=-1; for(int i=0;i<n;i++) if(tp[i]==k+1){pp=i;break;}
                if(pp==k){do_op(x,y);break;}
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
